namespace sv_79932796ccc64183b621efcdbfcce5c3.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A – East"),
        new("WH-002", "Warehouse B – West"),
        new("WH-003", "Warehouse C – Central"),
        new("WH-004", "Warehouse D – North"),
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_79932796ccc64183b621efcdbfcce5c3.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for a single user circuit.
/// Polling is reference-counted: multiple components can request polling, and it
/// stops only when all have unsubscribed.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _lastAlertCount;

    public int CurrentAlertCount => _lastAlertCount;

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a background thread.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling (reference counted). Call StopPolling when done.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
            // Trigger an immediate first poll
            _ = RefreshAsync();
        }
    }

    /// <summary>
    /// Stop polling (reference counted). Polling stops when all subscribers unsubscribe.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopTimer();
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose/stop
        }
    }

    private async Task RefreshAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        _lastAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private void OnWarehouseChanged()
    {
        // When warehouse changes, refresh immediately if polling is active
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopTimer();
    }
}

