namespace sv_79932796ccc64183b621efcdbfcce5c3.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A – East"),
        new("WH-002", "Warehouse B – West"),
        new("WH-003", "Warehouse C – Central"),
        new("WH-004", "Warehouse D – North"),
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

